export function createViewConfirmExitGame(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const view = createContainerFromViewData(scene, viewConfirmExitGameData);

  const uiDialogBgLightNine40 = createAssetChild(scene, viewConfirmExitGameData.children['ui.dialog.bg.light.nine.40']);
  setLeftTop(
    uiDialogBgLightNine40,
    viewConfirmExitGameData.children['ui.dialog.bg.light.nine.40'].x - viewConfirmExitGameData.width / 2,
    viewConfirmExitGameData.children['ui.dialog.bg.light.nine.40'].y - viewConfirmExitGameData.height / 2,
  );

  const buttonConfirmExitNo = buildButtonConfirmExitNo(scene);
  setLeftTop(
    buttonConfirmExitNo,
    viewConfirmExitGameData.children['button.ConfirmExit.no'].x - viewConfirmExitGameData.width / 2,
    viewConfirmExitGameData.children['button.ConfirmExit.no'].y - viewConfirmExitGameData.height / 2,
  );

  const buttonConfirmExitYes = buildButtonConfirmExitYes(scene);
  setLeftTop(
    buttonConfirmExitYes,
    viewConfirmExitGameData.children['button.ConfirmExit.yes'].x - viewConfirmExitGameData.width / 2,
    viewConfirmExitGameData.children['button.ConfirmExit.yes'].y - viewConfirmExitGameData.height / 2,
  );

  const textConfirmExitGameTitle = createTextView(scene,  viewConfirmExitGameData.children['text.ConfirmExitGame.title'].text, {
    style: {
      color: '#FFB224'
    }
  });
  setLeftTop(
    textConfirmExitGameTitle,
    viewConfirmExitGameData.children['text.ConfirmExitGame.title'].x - viewConfirmExitGameData.width / 2,
    viewConfirmExitGameData.children['text.ConfirmExitGame.title'].y - viewConfirmExitGameData.height / 2,
  );

  const textConfirmExitGameMessage = createTextChild(scene, viewConfirmExitGameData.children['text.ConfirmExitGame.message']);
  setLeftTop(
    textConfirmExitGameMessage,
    viewConfirmExitGameData.children['text.ConfirmExitGame.message'].x - viewConfirmExitGameData.width / 2,
    viewConfirmExitGameData.children['text.ConfirmExitGame.message'].y - viewConfirmExitGameData.height / 2,
  );

  makeAlign(align => {
    align.anchor(uiDialogBgLightNine40).centerX(textConfirmExitGameTitle);
    align.anchor(uiDialogBgLightNine40).centerX(textConfirmExitGameMessage);
    align.anchor(uiDialogBgLightNine40).centerX(layoutChain({
      children: [buttonConfirmExitNo, buttonConfirmExitYes],
      alignToAnchor: AlignMethod.CENTER_Y,
      alignToNext: AlignMethod.RIGHT_TO,
      nextOffsetX: 20
    }));
  })

  view.add([
      uiDialogBgLightNine40,
    textConfirmExitGameTitle,
    textConfirmExitGameMessage,
    buttonConfirmExitNo,
    buttonConfirmExitYes,
  ]);

  return view;
}

/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildButtonConfirmExitNo(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const data = viewConfirmExitGameData.children['button.ConfirmExit.no'];
  const view = createContainerFromViewData(scene, data);

  const uiButtonGreenHeight82Nine36 = createAssetChild(scene, data.children['ui.button.green.height82.nine.36']);
  setLeftTop(
    uiButtonGreenHeight82Nine36,
    data.children['ui.button.green.height82.nine.36'].x - data.width / 2,
    data.children['ui.button.green.height82.nine.36'].y - data.height / 2,
  );
  view.add(uiButtonGreenHeight82Nine36);

  const textConfirmExitNo = createTextChild(scene, data.children['text.ConfirmExit.no']);
  setLeftTop(
    textConfirmExitNo,
    data.children['text.ConfirmExit.no'].x - data.width / 2,
    data.children['text.ConfirmExit.no'].y - data.height / 2,
  );
  view.add(textConfirmExitNo);

  centerX(uiButtonGreenHeight82Nine36, textConfirmExitNo);

  return view;
}

