export interface ICreateViewBgShopProps {
  scene: Phaser.Scene;
  backgrounds: ThemeBackground[];
}

export function createViewBgShop(props: ICreateViewBgShopProps): Phaser.GameObjects.Container {
  const { scene, backgrounds } = props;
  const view = createContainerFromViewData(scene, viewBgShopData);

  const uiDialogBgLightNine40 = createAssetChild(scene, viewBgShopData.children['ui.dialog.bg.light.nine.40']);
  setLeftTop(
    uiDialogBgLightNine40,
    viewBgShopData.children['ui.dialog.bg.light.nine.40'].x - viewBgShopData.width / 2,
    viewBgShopData.children['ui.dialog.bg.light.nine.40'].y - viewBgShopData.height / 2,
  );
  view.add(uiDialogBgLightNine40);

  const bgShopContent = createBgShopContent({ scene, backgrounds });
  makeAlign(align => {
    align.anchor(uiDialogBgLightNine40).centerX(bgShopContent);
    const topIn = viewBgShopData.children['bg-prev.castle.basic'].y;
    align.anchor(uiDialogBgLightNine40).topIn(bgShopContent, topIn);
  })
  view.add(bgShopContent);

  // const buttonStyleShopSelect = buildButtonStyleShopSelect(scene);
  // setLeftTop(
  //   buttonStyleShopSelect,
  //   viewBgShopData.children['button.StyleShopSelect'].x - viewBgShopData.width / 2,
  //   viewBgShopData.children['button.StyleShopSelect'].y - viewBgShopData.height / 2,
  // );
  // view.add(buttonStyleShopSelect);

  // const bgPrevSelected = createAssetChild(scene, viewBgShopData.children['bg-prev-selected']);
  // setLeftTop(
  //   bgPrevSelected,
  //   viewBgShopData.children['bg-prev-selected'].x - viewBgShopData.width / 2,
  //   viewBgShopData.children['bg-prev-selected'].y - viewBgShopData.height / 2,
  // );
  // view.add(bgPrevSelected);
  //
  // const iconCheckmark64 = createAssetChild(scene, viewBgShopData.children['icon.checkmark.64']);
  // setLeftTop(
  //   iconCheckmark64,
  //   viewBgShopData.children['icon.checkmark.64'].x - viewBgShopData.width / 2,
  //   viewBgShopData.children['icon.checkmark.64'].y - viewBgShopData.height / 2,
  // );
  // view.add(iconCheckmark64);

  const textBgShopTitle = createTextChild(scene, viewBgShopData.children.textBgShopTitle);
  setLeftTop(
    textBgShopTitle,
    viewBgShopData.children.textBgShopTitle.x - viewBgShopData.width / 2,
    viewBgShopData.children.textBgShopTitle.y - viewBgShopData.height / 2,
  );
  centerX(uiDialogBgLightNine40, textBgShopTitle);
  view.add(textBgShopTitle);

  const buttonBack = createButtonBack(scene);
  setLeftTop(
    buttonBack,
    viewBgShopData.children.buttonBack.x - viewBgShopData.width / 2,
    viewBgShopData.children.buttonBack.y - viewBgShopData.height / 2,
  );
  view.add(buttonBack);

  const bgOpacityControl = createBgOpacityControl({ scene });
  makeAlign(align => {
    align.anchor(uiDialogBgLightNine40).centerX(bgOpacityControl).bottomIn(bgOpacityControl, -32);
  });
  view.add(bgOpacityControl);

  return view;
}

/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildButtonStyleShopSelect(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const data = viewBgShopData.children['button.StyleShopSelect'];
  const view = createContainerFromViewData(scene, data);

  const btStyleShopSelectSelectNine15 = createAssetChild(scene, data.children['btStyleShopSelect.select.nine.15']);
  setLeftTop(
    btStyleShopSelectSelectNine15,
    data.children['btStyleShopSelect.select.nine.15'].x - data.width / 2,
    data.children['btStyleShopSelect.select.nine.15'].y - data.height / 2,
  );
  view.add(btStyleShopSelectSelectNine15);

  const textBtStyleShopSelect = createTextChild(scene, data.children.textBtStyleShopSelect);
  setLeftTop(
    textBtStyleShopSelect,
    data.children.textBtStyleShopSelect.x - data.width / 2,
    data.children.textBtStyleShopSelect.y - data.height / 2,
  );
  view.add(textBtStyleShopSelect);

  return view;
}
