import { ILogicShopItem } from "../../../logic";
import { GameServiceProvider } from "../../../services";

export function getAvailableGameShopItems(): ILogicShopItem[] {
  const gameService = GameServiceProvider.get();
  const shopItems = Object.values(gameService.getShopItems() ?? {});
  const isRewardEnabled = gameService.isRewardAdEnabled;
  return shopItems.filter((item) => (item.rewardAdPrice ? isRewardEnabled : true));
}

export function isGameShopAvailable(): boolean {
  const gameService = GameServiceProvider.get();
  if (!gameService.isShopEnabled) {
    return false;
  }

  return getAvailableGameShopItems().length > 0;
}
