import { SceneEvents } from "../../../common";
import { ConsumableAmounts } from "../../../logic";
import { GameServiceProvider } from "../../../services";
import { IGameCommonAdCloseResult, IGameRewardedAdCloseResult, IGameEvents } from "../../events";
import { SpiderGameScenes } from "../../scenes";
import { pauseParentSceneAudio } from "../../shared/ads";

interface ISpiderGameAdsSceneLauncherProps {
  scene: Phaser.Scene;
}

export class SpiderGameAdsSceneLauncher {
  private readonly sceneEvents: SceneEvents<IGameEvents>;

  constructor(private readonly props: ISpiderGameAdsSceneLauncherProps) {
    this.sceneEvents = new SceneEvents<IGameEvents>({ scene: props.scene });
    this.sceneEvents.on("gameRequestForCommonAd", () => this.handleGameRequestForCommonAd());
    this.sceneEvents.on("gameRequestForRewardedAd", (data) => this.handleGameRequestForRewardedAd(data));
  }

  /**
   * Контракт:
   * - сюда приходит намерение игры показать обычную рекламу
   * - посредник сам повторяет старые guard-условия common ad
   * - только после этого он подписывается на завершение и запускает ad-scene
   */
  private handleGameRequestForCommonAd(): void {
    if (!this.canLaunchCommonAd()) {
      return;
    }

    this.sceneEvents.once("gameCommonAdClosed", (result) => {
      if (result == null) {
        return;
      }

      this.handleGameCommonAdClosed(result);
    });

    pauseParentSceneAudio({ parentScene: this.props.scene });
    this.props.scene.scene.launch(SpiderGameScenes.CommonAd, {
      parentSceneKey: this.props.scene.scene.key,
    });
    this.props.scene.scene.bringToTop(SpiderGameScenes.CommonAd);
  }

  /**
   * Контракт:
   * - сюда приходит намерение игры показать rewarded ad c конкретной наградой
   * - посредник повторяет старые guard-условия reward ad
   * - только после этого он подписывается на финальный результат и запускает ad-scene
   */
  private handleGameRequestForRewardedAd(data: IGameEvents["gameRequestForRewardedAd"]): void {
    if (!this.canLaunchRewardedAd(data.rewardsAmount)) {
      return;
    }

    this.sceneEvents.once("gameRewardedAdClosed", (result) => {
      if (result == null) {
        return;
      }

      this.handleGameRewardedAdClosed(result);
    });

    pauseParentSceneAudio({ parentScene: this.props.scene });
    this.props.scene.scene.launch(SpiderGameScenes.RewardAd, {
      parentSceneKey: this.props.scene.scene.key,
      rewardsAmount: data.rewardsAmount,
    });
    this.props.scene.scene.bringToTop(SpiderGameScenes.RewardAd);
  }

  private isAnyAdSceneActive(): boolean {
    return this.props.scene.scene.isActive(SpiderGameScenes.CommonAd)
      || this.props.scene.scene.isActive(SpiderGameScenes.RewardAd);
  }

  private canLaunchCommonAd(): boolean {
    if (this.isAnyAdSceneActive()) {
      return false;
    }

    return GameServiceProvider.get().isFullAdEnabled;
  }

  private canLaunchRewardedAd(rewardsAmount: ConsumableAmounts): boolean {
    if (this.isAnyAdSceneActive()) {
      return false;
    }

    if (!GameServiceProvider.get().isRewardAdEnabled) {
      return false;
    }

    return Object.values(rewardsAmount).some((amount) => amount > 0);
  }

  /**
   * Контракт:
   * - обработчик срабатывает на любое завершение common ad
   * - досрочное закрытие и штатное завершение обе считаются концом flow
   * - побочных эффектов в игре пока нет, но точка завершения теперь единая
   */
  private handleGameCommonAdClosed(result: IGameCommonAdCloseResult): void {
    void result;
  }

  /**
   * Контракт:
   * - обработчик получает уже финальный результат rewarded ad
   * - при досрочном закрытии или отсутствии награды расходники не начисляются
   * - при успешном завершении начисляем награду так же централизованно через посредник
   */
  private handleGameRewardedAdClosed(result: IGameRewardedAdCloseResult): void {
    if (!result.isReward || result.rewardsAmount == null) {
      return;
    }

    this.addRewards(result.rewardsAmount);
    this.sceneEvents.emit("gameConsumablesUpdated");
  }

  private addRewards(rewardsAmount: ConsumableAmounts): void {
    const gameService = GameServiceProvider.get();
    const playerData = gameService.getPlayerData();
    const nextConsumables: ConsumableAmounts = {
      ...playerData.consumables,
    };

    Object.entries(rewardsAmount).forEach(([key, amount]) => {
      const type = key as keyof ConsumableAmounts;
      nextConsumables[type] = (nextConsumables[type] ?? 0) + (amount ?? 0);
    });

    gameService.setPlayerData({
      consumables: nextConsumables,
    });
  }
}
