import {GamePlayerData} from './types';

export const mergePlayerData = (
    target: GamePlayerData,
    options: Partial<GamePlayerData> = {},
): GamePlayerData => {
    return {
        settings: {
            ...target.settings,
            ...options.settings,
        },
        consumables: {
            UNDO: options.consumables?.UNDO ?? target.consumables.UNDO,
            HINT: options.consumables?.HINT ?? target.consumables.HINT,
            MAGIC: options.consumables?.MAGIC ?? target.consumables.MAGIC,
        },
        spider: {
            ...target.spider,
            ...options.spider,
        },
        gold: options.gold ?? target.gold
    };
};
